inline RFST::RFST(const RFST &o)
      : MATERIAL_ID(o.MATERIAL_ID),
        NAME(o.NAME),
        MATERIAL_CLASS(o.MATERIAL_CLASS),
        DESCRIPTION(o.DESCRIPTION),
        FREQUENCY_MIN_MHZ(o.FREQUENCY_MIN_MHZ),
        FREQUENCY_MAX_MHZ(o.FREQUENCY_MAX_MHZ),
        PERMITTIVITY_COEFFICIENT_A(o.PERMITTIVITY_COEFFICIENT_A),
        PERMITTIVITY_EXPONENT_B(o.PERMITTIVITY_EXPONENT_B),
        CONDUCTIVITY_COEFFICIENT_C(o.CONDUCTIVITY_COEFFICIENT_C),
        CONDUCTIVITY_EXPONENT_D(o.CONDUCTIVITY_EXPONENT_D),
        REFERENCE_FREQUENCY_MHZ(o.REFERENCE_FREQUENCY_MHZ),
        RELATIVE_PERMITTIVITY_REAL(o.RELATIVE_PERMITTIVITY_REAL),
        RELATIVE_PERMITTIVITY_IMAGINARY(o.RELATIVE_PERMITTIVITY_IMAGINARY),
        CONDUCTIVITY_S_PER_M(o.CONDUCTIVITY_S_PER_M),
        LOSS_TANGENT(o.LOSS_TANGENT),
        RELATIVE_PERMEABILITY_REAL(o.RELATIVE_PERMEABILITY_REAL),
        RELATIVE_PERMEABILITY_IMAGINARY(o.RELATIVE_PERMEABILITY_IMAGINARY),
        REFLECTIVITY(o.REFLECTIVITY),
        REFLECTION_LOSS_DB(o.REFLECTION_LOSS_DB),
        THICKNESS_M(o.THICKNESS_M),
        TRANSMISSION_LOSS_DB(o.TRANSMISSION_LOSS_DB),
        ATTENUATION_DB_PER_M(o.ATTENUATION_DB_PER_M),
        ABSORPTION_COEFFICIENT(o.ABSORPTION_COEFFICIENT),
        SURFACE_ROUGHNESS_RMS_M(o.SURFACE_ROUGHNESS_RMS_M),
        ROUGHNESS_CORRELATION_LENGTH_M(o.ROUGHNESS_CORRELATION_LENGTH_M),
        SCATTERING_CLASS(o.SCATTERING_CLASS),
        DIFFUSE_SCATTERING_COEFFICIENT(o.DIFFUSE_SCATTERING_COEFFICIENT),
        BACKSCATTER_COEFFICIENT_DB(o.BACKSCATTER_COEFFICIENT_DB),
        TEMPERATURE_K(o.TEMPERATURE_K),
        MOISTURE_CONTENT_FRACTION(o.MOISTURE_CONTENT_FRACTION),
        SALINITY_PSU(o.SALINITY_PSU),
        PROVENANCE((o.PROVENANCE) ? new RFSProvenanceT(*o.PROVENANCE) : nullptr),
        COMPUTED_AT(o.COMPUTED_AT),
        PRODUCER_ID(o.PRODUCER_ID),
        SIGNATURE(o.SIGNATURE) {
  FREQUENCY_SAMPLES.reserve(o.FREQUENCY_SAMPLES.size());
  for (const auto &FREQUENCY_SAMPLES_ : o.FREQUENCY_SAMPLES) { FREQUENCY_SAMPLES.emplace_back((FREQUENCY_SAMPLES_) ? new RFSFrequencySampleT(*FREQUENCY_SAMPLES_) : nullptr); }
  REFLECTION_TABLE.reserve(o.REFLECTION_TABLE.size());
  for (const auto &REFLECTION_TABLE_ : o.REFLECTION_TABLE) { REFLECTION_TABLE.emplace_back((REFLECTION_TABLE_) ? new RFSReflectionEntryT(*REFLECTION_TABLE_) : nullptr); }
  GEOMETRY.reserve(o.GEOMETRY.size());
  for (const auto &GEOMETRY_ : o.GEOMETRY) { GEOMETRY.emplace_back((GEOMETRY_) ? new RFSGeometryRefT(*GEOMETRY_) : nullptr); }
}

