inline const RFS *GetRFS(const void *buf) {
  return ::flatbuffers::GetRoot<RFS>(buf);
}

inline const RFS *GetSizePrefixedRFS(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<RFS>(buf);
}

inline const char *RFSIdentifier() {
  return "$RFS";
}

inline bool RFSBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, RFSIdentifier());
}

inline bool SizePrefixedRFSBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, RFSIdentifier(), true);
}

template <bool B = false>
inline bool VerifyRFSBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<RFS>(RFSIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedRFSBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<RFS>(RFSIdentifier());
}

inline void FinishRFSBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<RFS> root) {
  fbb.Finish(root, RFSIdentifier());
}

inline void FinishSizePrefixedRFSBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<RFS> root) {
  fbb.FinishSizePrefixed(root, RFSIdentifier());
}

inline std::unique_ptr<RFST> UnPackRFS(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<RFST>(GetRFS(buf)->UnPack(res));
}

inline std::unique_ptr<RFST> UnPackSizePrefixedRFS(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<RFST>(GetSizePrefixedRFS(buf)->UnPack(res));
}

